{
  "themes": [
    {
      "cluster": 12,
      "name": "Excessive Phone Hold Times",
      "description": "Customers complain about being placed on hold for long periods, often over an hour, when trying to reach support."
    },
    {
      "cluster": 13,
      "name": "General Negative Sentiment Toward Service",
      "description": "Customers express strong dissatisfaction and use profanity toward the brand or its representatives."
    },
    {
      "cluster": 14,
      "name": "SkyMiles Account Issues",
      "description": "Customers report problems with mileage accrual, incorrect account numbers, and delays in account updates."
    },
    {
      "cluster": 15,
      "name": "Seat Upgrade Requests and Confusion",
      "description": "Customers ask about upgrading seats, using points for upgrades, and encounter unclear seat labeling."
    },
    {
      "cluster": 16,
      "name": "Standby Status Concerns",
      "description": "Customers are confused or frustrated about being placed on standby for upcoming flights and related support wait times."
    },
    {
      "cluster": 17,
      "name": "General Help and Assistance Requests",
      "description": "Customers reach out seeking help or answers to questions without specifying a particular issue."
    },
    {
      "cluster": 18,
      "name": "In‑Flight Food and Snack Feedback",
      "description": "Customers share opinions, cravings, and complaints about the meals, snacks, and dietary options offered on flights."
    },
    {
      "cluster": 19,
      "name": "Flight Delay Frustrations",
      "description": "Customers express annoyance over long or repeated flight delays and the impact on their travel plans."
    },
    {
      "cluster": 20,
      "name": "Cabin Cleanliness and Odor Complaints",
      "description": "Customers report unpleasant smells, unclean restrooms, and overall cabin hygiene issues."
    },
    {
      "cluster": 21,
      "name": "Reservation Errors and Support Delays",
      "description": "Customers experience problems with reservations and cite long hold times when seeking resolution."
    },
    {
      "cluster": 22,
      "name": "App/Website Access and Crash Problems",
      "description": "Customers encounter login failures, app crashes, and general unavailability of the digital platform."
    },
    {
      "cluster": 23,
      "name": "Overall Airline Experience Complaints",
      "description": "Customers voice broad dissatisfaction with boarding, airport lounges, and overall airline service quality."
    }
  ]
}
